// server/api/auth/login.post.ts
import type { LoginPayload, AuthResponse } from '~/types/Auth'

export default defineEventHandler(async (event) => {
  const config = useRuntimeConfig()
  const body   = await readBody<LoginPayload>(event)

  if (!body?.email || !body?.password) {
    throw createError({ statusCode: 400, message: 'Email et mot de passe requis' })
  }

  const data = await $fetch<AuthResponse>(`${config.railsApiBase}/auth/login`, {
    method: 'POST',
    body
  })

  // Le token ne touche JAMAIS le JS client — cookie httpOnly uniquement
  setCookie(event, 'auth_token', data.token, {
    httpOnly: true,
    secure:   process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge:   60 * 60 * 24 * 7  // 7 jours
  })

  // On renvoie l'utilisateur mais JAMAIS le token
  return { user: data.user }
})

