// stores/useAuthStore.ts
import type { User } from '~/types/Auth'

export const useAuthStore = defineStore('auth', {
  state: () => ({
    user: null as User | null
  }),

  getters: {
    isAuthenticated: (state): boolean => !!state.user,
    userId: (state): number | null => state.user?.id ?? null
  },

  actions: {
    setUser(user: User) {
      this.user = user
    },
    logout() {
      this.user = null
    }
  }
})

// composables/useAuth.ts
import type { LoginPayload, RegisterPayload } from '~/types/Auth'

export const useAuth = () => {
  const store = useAuthStore()

  const login = async (payload: LoginPayload) => {
    const { user } = await $fetch('/api/auth/login', {
      method: 'POST',
      body: payload,
      credentials: 'include'
    })
    store.setUser(user)
    return user
  }

  const register = async (payload: RegisterPayload) => {
    const { user } = await $fetch('/api/auth/register', {
      method: 'POST',
      body: payload,
      credentials: 'include'
    })
    store.setUser(user)
    return user
  }

  const logout = async () => {
    await $fetch('/api/auth/logout', { method: 'POST', credentials: 'include' })
    store.logout()
    await navigateTo('/login')
  }

  // Hydrate le store depuis Rails au chargement (SSR safe)
  const fetchMe = async () => {
    try {
      const user = await $fetch('/api/auth/me', { credentials: 'include' })
      store.setUser(user)
    } catch {
      store.logout()
    }
  }

  return { login, register, logout, fetchMe }
}

// middleware/auth.ts
export default defineNuxtRouteMiddleware(() => {
  const authStore = useAuthStore()
  if (!authStore.isAuthenticated) {
    return navigateTo('/login')
  }
})

// middleware/guest.ts
export default defineNuxtRouteMiddleware(() => {
  const authStore = useAuthStore()
  if (authStore.isAuthenticated) {
    return navigateTo('/')
  }
})

// plugins/auth.ts
export default defineNuxtPlugin(async () => {
  const { fetchMe } = useAuth()
  // Hydrate uniquement côté client pour éviter les problèmes SSR avec les cookies
  if (import.meta.client) {
    await fetchMe()
  }
})

// composables/useNotification.ts
type NotificationType = 'success' | 'error' | 'warning' | 'info'

const state = reactive({
  show:    false,
  message: '',
  type:    'success' as NotificationType,
  timeout: 3000
})

export const useNotification = () => {
  const notify = (message: string, type: NotificationType = 'success', timeout = 3000) => {
    state.message = message
    state.type    = type
    state.timeout = timeout
    state.show    = true
  }

  const success = (message: string) => notify(message, 'success')
  const error   = (message: string) => notify(message, 'error')
  const warning = (message: string) => notify(message, 'warning')

  return { state, notify, success, error, warning }
}

