import { describe, it, expect, vi, beforeEach } from 'vitest'
import { mockNuxtImport } from '@nuxt/test-utils/runtime'

const mockFetch = vi.fn()
vi.mock('ofetch', () => ({ $fetch: mockFetch }))

const mockSetCookie = vi.fn()
const mockReadBody  = vi.fn()
mockNuxtImport('setCookie',        () => mockSetCookie)
mockNuxtImport('readBody',         () => mockReadBody)
mockNuxtImport('useRuntimeConfig', () => vi.fn(() => ({ railsApiBase: 'http://rails.test' })))

describe('POST /api/auth/login', () => {
  beforeEach(() => vi.clearAllMocks())

  it('retourne 400 si email ou password manquant', async () => {
    mockReadBody.mockResolvedValue({ email: '', password: '' })
    const handler = (await import('~/server/api/auth/login.post')).default
    await expect(handler({} as any)).rejects.toMatchObject({ statusCode: 400 })
  })

  it('pose le cookie httpOnly et retourne user sans token', async () => {
    mockReadBody.mockResolvedValue({ email: 'test@test.com', password: 'password123' })
    mockFetch.mockResolvedValue({
      token: 'secret-jwt',
      user:  { id: 1, email: 'test@test.com', name: 'Test' }
    })

    const handler = (await import('~/server/api/auth/login.post')).default
    const result  = await handler({} as any)

    // Le token doit être dans le cookie, jamais dans la réponse
    expect(mockSetCookie).toHaveBeenCalledWith(
      expect.anything(),
      'auth_token',
      'secret-jwt',
      expect.objectContaining({ httpOnly: true })
    )
    expect(result).toEqual({ user: { id: 1, email: 'test@test.com', name: 'Test' } })
    expect(JSON.stringify(result)).not.toContain('secret-jwt')
  })
})

