import { describe, it, expect, vi, beforeEach } from 'vitest'
import { mockNuxtImport } from '@nuxt/test-utils/runtime'

const mockFetch       = vi.fn()
const mockDeleteCookie = vi.fn()
const mockGetCookie   = vi.fn()

vi.mock('ofetch', () => ({ $fetch: mockFetch }))
mockNuxtImport('deleteCookie',     () => mockDeleteCookie)
mockNuxtImport('getCookie',        () => mockGetCookie)
mockNuxtImport('useRuntimeConfig', () => vi.fn(() => ({ railsApiBase: 'http://rails.test' })))

describe('POST /api/auth/logout', () => {
  beforeEach(() => vi.clearAllMocks())

  it('supprime le cookie et retourne { success: true }', async () => {
    mockGetCookie.mockReturnValue('token-123')
    mockFetch.mockResolvedValue(undefined)

    const handler = (await import('~/server/api/auth/logout.post')).default
    const result  = await handler({} as any)

    expect(mockDeleteCookie).toHaveBeenCalledWith(expect.anything(), 'auth_token')
    expect(result).toEqual({ success: true })
  })

  it('supprime le cookie même si Rails échoue', async () => {
    mockGetCookie.mockReturnValue('token-123')
    mockFetch.mockRejectedValue(new Error('Rails down'))

    const handler = (await import('~/server/api/auth/logout.post')).default
    const result  = await handler({} as any)

    expect(mockDeleteCookie).toHaveBeenCalled()
    expect(result).toEqual({ success: true })
  })

  it('supprime le cookie même sans token', async () => {
    mockGetCookie.mockReturnValue(undefined)

    const handler = (await import('~/server/api/auth/logout.post')).default
    const result  = await handler({} as any)

    expect(mockFetch).not.toHaveBeenCalled()
    expect(mockDeleteCookie).toHaveBeenCalled()
    expect(result).toEqual({ success: true })
  })
})

