import { describe, it, expect, vi, beforeEach } from 'vitest'
import { setActivePinia, createPinia } from 'pinia'
import { mockNuxtImport } from '@nuxt/test-utils/runtime'

const mockFetch      = vi.fn()
const mockNavigateTo = vi.fn()

vi.mock('ofetch', () => ({ $fetch: mockFetch }))
mockNuxtImport('navigateTo', () => mockNavigateTo)

describe('useAuth', () => {
  beforeEach(() => {
    setActivePinia(createPinia())
    vi.clearAllMocks()
  })

  it('login() appelle /api/auth/login et met à jour le store', async () => {
    const user = { id: 1, email: 'test@test.com', name: 'Test' }
    mockFetch.mockResolvedValue({ user })

    const { useAuth }     = await import('~/composables/useAuth')
    const { useAuthStore } = await import('~/stores/useAuthStore')
    const { login } = useAuth()
    const store     = useAuthStore()

    await login({ email: 'test@test.com', password: 'password' })

    expect(mockFetch).toHaveBeenCalledWith('/api/auth/login', expect.objectContaining({ method: 'POST' }))
    expect(store.user).toEqual(user)
    expect(store.isAuthenticated).toBe(true)
  })

  it('logout() vide le store et redirige vers /login', async () => {
    mockFetch.mockResolvedValue(undefined)

    const { useAuth }     = await import('~/composables/useAuth')
    const { useAuthStore } = await import('~/stores/useAuthStore')
    const { logout } = useAuth()
    const store      = useAuthStore()
    store.setUser({ id: 1, email: 'test@test.com' })

    await logout()

    expect(store.user).toBeNull()
    expect(mockNavigateTo).toHaveBeenCalledWith('/login')
  })

  it('fetchMe() hydrate le store si token valide', async () => {
    const user = { id: 1, email: 'me@test.com' }
    mockFetch.mockResolvedValue(user)

    const { useAuth }     = await import('~/composables/useAuth')
    const { useAuthStore } = await import('~/stores/useAuthStore')
    const { fetchMe } = useAuth()
    const store       = useAuthStore()

    await fetchMe()

    expect(store.user).toEqual(user)
  })

  it('fetchMe() vide le store si token invalide', async () => {
    mockFetch.mockRejectedValue(new Error('401'))

    const { useAuth }     = await import('~/composables/useAuth')
    const { useAuthStore } = await import('~/stores/useAuthStore')
    const { fetchMe } = useAuth()
    const store       = useAuthStore()
    store.setUser({ id: 1, email: 'test@test.com' })

    await fetchMe()

    expect(store.user).toBeNull()
  })
})

