// Utilise la session authentifiée (storageState chargé depuis playwright.config.ts)
import { test, expect } from '@playwright/test'

test.describe('Logout', () => {

  test('déconnecte et redirige vers /login', async ({ page }) => {
    await page.goto('/')

    // Adapter le sélecteur selon ton layout (bouton logout dans la navbar)
    await page.getByRole('button', { name: /déconnexion|logout|quitter/i }).click()

    await expect(page).toHaveURL('/login', { timeout: 5000 })
  })

  test('les pages protégées sont inaccessibles après logout', async ({ page }) => {
    await page.goto('/')
    await page.getByRole('button', { name: /déconnexion|logout|quitter/i }).click()
    await expect(page).toHaveURL('/login')

    // Tenter d'accéder à une route protégée
    await page.goto('/articles')
    await expect(page).toHaveURL('/login')
  })

